return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'mn','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:00+00:00','po-revision-date'=>'2026-11-05T19:51:00+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Таны сайтад суулгасан плагин болон сэдвүүдийн дутуу орчуулгыг автоматаар нөхнө.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Тухайн байршуулах дэлгэц хуучирсан байна: түүнээс хойш өөр байршуулалт бэлтгэгдсэн. Юу ч илгээгдсэнгүй. Одоогийн байршуулалтыг Орчуулгын жагсаалтаас хянана уу.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Үнэгүй үйлчилгээний багц нь сайт бүрт плагин болон сэдвүүдэд зориулсан хязгаарлагдмал тооны слот олгодог; Babilim-ийг идэвхжүүлсний дараа ашиглагдаж буй слотуудыг Тохиргоо хэсгээс харж болно.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Орчуулга хүсэхэд энэ плагин эсвэл сэдэв энэ сайтын үнэгүй үйлчилгээний багцын слотуудын нэг дээр орно (хязгаар нь сэдвийн хувьд %1$d, плагины хувьд %2$d), хэрэв аль хэдийн слоттой бол орохгүй. Слот ашиглагдсан хэвээр үлдэх бөгөөд амжилтгүй болсон орчуулга слотыг чөлөөлөхгүй.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Орчуулга хүсэхэд энэ плагин эсвэл сэдэв энэ сайтын үнэгүй үйлчилгээний багцын слотуудын нэг дээр орно, хэрэв аль хэдийн слоттой бол орохгүй. Слот ашиглагдсан хэвээр үлдэх бөгөөд амжилтгүй болсон орчуулга слотыг чөлөөлөхгүй.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Хэрэв энэ плагин эсвэл сэдэв энэ сайтын үнэгүй үйлчилгээний багцын слотуудын нэг дээр хараахан ороогүй бол орчуулга хүсэхэд нэг слот дээр орно (хязгаар нь сэдвийн хувьд %1$d, плагины хувьд %2$d). Слот ашиглагдсан хэвээр үлдэх бөгөөд амжилтгүй болсон орчуулга слотыг чөлөөлөхгүй. Үргэлжлүүлэх үү?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Хэрэв энэ плагин эсвэл сэдэв энэ сайтын үнэгүй үйлчилгээний багцын слотуудын нэг дээр хараахан ороогүй бол орчуулга хүсэхэд нэг слот дээр орно. Слот ашиглагдсан хэвээр үлдэх бөгөөд амжилтгүй болсон орчуулга слотыг чөлөөлөхгүй. Үргэлжлүүлэх үү?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Энэ сүлжээний %1$d сайт плагиныг устгах үед Babilim-ийн таниулбараа устгахаар тохируулагдсан байна. Тэр сайтад холбогдсон төлбөртэй лицензийг автоматаар сэргээх боломжгүй болно; та %2$s хаягаар Babilim-ийн дэмжлэгтэй холбогдох шаардлагатай. Таниулбарыг хадгалахын тулд Цуцлах дээр дарж, тухайн сайтын Babilim-ийн тохиргоонд "Устгах үед Babilim-ийн бүх өгөгдлийг устгах" сонголтыг болиулаад, дахин идэвхгүй болгоно уу. Ямар ч тохиолдолд идэвхгүй болгох уу?' . "\0" . 'Энэ сүлжээний %1$d сайт плагиныг устгах үед Babilim-ийн таниулбараа устгахаар тохируулагдсан байна. Тэдгээр сайтад холбогдсон төлбөртэй лицензийг автоматаар сэргээх боломжгүй болно; та %2$s хаягаар Babilim-ийн дэмжлэгтэй холбогдох шаардлагатай. Таниулбаруудыг хадгалахын тулд Цуцлах дээр дарж, сайт тус бүрийн Babilim-ийн тохиргоонд "Устгах үед Babilim-ийн бүх өгөгдлийг устгах" сонголтыг болиулаад, дахин идэвхгүй болгоно уу. Ямар ч тохиолдолд идэвхгүй болгох уу?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s хийх зүйл алга.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Хэлийг сонгоно уу.','%d failed'=>'%d амжилтгүй' . "\0" . '%d амжилтгүй','%d not yet tried'=>'%d хараахан оролдоогүй' . "\0" . '%d хараахан оролдоогүй','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d тайлан хүлээгдэж байна. "Үргэлж хуваалцах" болон "Хуваалцахгүй" нь бүгдэд нь хамаарна.' . "\0" . '%d тайлан хүлээгдэж байна. "Үргэлж хуваалцах" болон "Хуваалцахгүй" нь бүгдэд нь хамаарна.','%d skipped'=>'%d алгассан' . "\0" . '%d алгассан','%d succeeded'=>'%d амжилттай' . "\0" . '%d амжилттай','%d to install'=>'%d суулгах' . "\0" . '%d суулгах','(a public key generated for this site)'=>'(энэ сайтад зориулж үүсгэсэн нийтийн түлхүүр)','(detected)'=>'(илрүүлсэн)','(generic codes and coordinates only)'=>'(зөвхөн ерөнхий код болон координат)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s-д цэвэрлэгээг түр зогсоосон: %2$s. Юу ч устгагдаагүй.','A file in the component could not be read, so it was not packaged.'=>'Бүрэлдэхүүн хэсэг доторх нэг файлыг уншиж чадаагүй тул багцалсангүй.','A host that serves only one PHP request at a time cannot complete this step.'=>'Нэг удаад зөвхөн нэг PHP хүсэлт боловсруулдаг хост энэ алхмыг дуусгаж чадахгүй.','A part of the upload kept failing, so the upload was cancelled.'=>'Байршуулалтын нэг хэсэг удаа дараа амжилтгүй болсон тул байршуулалтыг цуцаллаа.','A translation cannot be requested for that locale on this site right now.'=>'Одоогоор энэ сайт дээр тухайн локалд орчуулга хүсэх боломжгүй байна.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Орчуулгын индексийн бичилт %1$s үед өөр хүсэлттэй зөрчилдсөн (%2$s) тул хэрэгжээгүй; хамгийн сүүлийн хувилбарыг хадгалсан.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Орчуулгын индексийн %1$s үеийн бичилт (%2$s) дуусгах боломжгүй байсан тул хэрэгжээгүй (%3$s).','Account'=>'Бүртгэл','Add another language'=>'Өөр хэл нэмэх','Advanced'=>'Нарийвчилсан','All'=>'Бүгд','All free-plan slots for this site are used'=>'Энэ сайтын үнэгүй багцын бүх слотыг ашигласан','All languages'=>'Бүх хэл','Already in WordPress core'=>'WordPress-ийн цөмд аль хэдийн орсон','Already installed.'=>'Аль хэдийн суулгасан.','Always share'=>'Үргэлж хуваалцах','Another installation is running; try again in a moment.'=>'Өөр суулгалт ажиллаж байна; жаахан хүлээгээд дахин оролдоно уу.','Automatic installs'=>'Автомат суулгалт','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Автомат суулгалт одоо унтарсан; хэрэв хүсвэл тохиргооноос дахин асаана уу.','Available'=>'Боломжтой','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Боломжтой орчуулгуудыг нэг товшилтоор суулгаж, дутуу орчуулгын хүсэлт илгээж болно. Автомат суулгалт идэвхтэй үед таны удирддаг хэлнүүдэд зориулан үйлчилгээнээс боломжтой гэж жагсаасан орчуулгуудыг өдөрт хоёр удаа хийгдэх синкийн үеэр суулгана.','Available · %s'=>'Боломжтой · %s','Babilim Settings'=>'Babilim-ийн тохиргоо','Babilim adds translations for every language checked here.'=>'Babilim энд сонгосон бүх хэлний орчуулгыг нэмдэг.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim вэбсайтаас гадна байрлах түр хавтсыг баталгаажуулж чадаагүй тул бүрэлдэхүүн хэсгийг багцлаагүй бөгөөд юу ч байршуулаагүй. wp-config.php дотор BABILIM_TEMP_DIR-ийг вэб үндсэн хавтсаас гадна байрлах бичих эрхтэй хавтсаар тодорхойлно уу (жишээ нь таны сайтын нийтийн хавтастай зэрэгцээ, гэхдээ түүний дотор биш хавтас), эсвэл хостоосоо асууна уу.','Babilim could not finish checking this site.'=>'Babilim энэ сайтын шалгалтыг дуусгаж чадсангүй.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim идэвхжүүлэлтийг дуусгаж чадсангүй (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim энэ сайтыг баталгаажуулж дуусгаж чадсангүй (үйлчилгээ сайтад буцаж холбогдож чадсангүй). Бүртгэл түр зогссон.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim энэ сайтыг баталгаажуулж чадаагүй тул баталгаажуулалт амжилттай болох хүртэл юу ч татаж авахгүй, суулгахгүй.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim энэ сайтыг баталгаажуулж чадаагүй тул юу ч татаж аваагүй, суулгаагүй.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim энэ сайт дээрх таны хэлний орчуулгагүй плагин, сэдвүүдийг олж, тус бүрт нь орчуулга суулгана.','Babilim has not been enabled for this site yet.'=>'Babilim энэ сайтад хараахан идэвхжээгүй байна.','Babilim has not installed any translation for this language.'=>'Babilim энэ хэлний ямар ч орчуулга суулгаагүй байна.','Babilim hit an error. Share an error report?'=>'Babilim алдаа гаргалаа. Алдааны тайлан хуваалцах уу?','Babilim installed %d translation automatically since your last visit.'=>'Babilim таны сүүлд зочилсноос хойш %d орчуулгыг автоматаар суулгалаа.' . "\0" . 'Babilim таны сүүлд зочилсноос хойш %d орчуулгыг автоматаар суулгалаа.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim идэвхгүй боллоо. Цаашид юу ч илгээгдэхгүй; суулгасан орчуулгууд үргэлжлүүлэн ажиллана.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim идэвхжсэн: энэ сайт баталгаажсан бөгөөд %d бүрэлдэхүүн хэсэг олдлоо.' . "\0" . 'Babilim идэвхжсэн: энэ сайт баталгаажсан бөгөөд %d бүрэлдэхүүн хэсэг олдлоо.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim энэ сайтыг идэвхжүүлж, шалгаж байна… (сүүлийн оролдлого: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim энэ сайтыг идэвхжүүлж, шалгаж байна… Энэ хуудсыг дахин ачаалах эсвэл хуваарьт шалгалт дуустал хүлээнэ үү.','Babilim is not enabled.'=>'Babilim идэвхжээгүй байна.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim нь плагиныг устгах үед энэ сайтын таниулбарыг устгахаар тохируулагдсан байна. Тэгвэл энэ сайтад холбогдсон төлбөртэй лицензийг автоматаар сэргээх боломжгүй болно; та %s хаягаар Babilim-ийн дэмжлэгтэй холбогдох шаардлагатай. Таниулбарыг хадгалахын тулд Цуцлах дээр дарж, Babilim-ийн тохиргоонд "Устгах үед Babilim-ийн бүх өгөгдлийг устгах" сонголтыг болиулаад, дахин идэвхгүй болгоно уу. Ямар ч тохиолдолд идэвхгүй болгох уу?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim-ийн энэ алхамд зориулсан хугацаа дууссан тул дараагийн шалгалтаар үргэлжлүүлнэ.','Babilim settings'=>'Babilim-ийн тохиргоо','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim-ийн синхрончлолыг үйлчилгээ түр хойшлуулсан (хүсэлтийн хязгаар); %s дараа дахин оролдоно.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Энэ байршуулалтыг хүлээж байх хооронд Babilim шинэчлэгдсэн. Хуучин багцыг устгасан; байршуулалтыг дахин баталгаажуулна уу.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim %1$s (хувилбар %2$s)-ийн эдгээр файлуудыг байршуулна: бүх .php болон .js файл, бүх block.json файл, мөн үндсэн хавтас доторх readme.txt, readme.md, style.css, theme.json. Эдгээрийг орчуулах шаардлагатай текстийг олох, мөн плагин эсвэл сэдвийг тодорхойлоход ашиглана.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ашиглах боломжгүй: %s','Back'=>'Буцах','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Энэ домэйнд өмнө нь лиценз худалдан авч байсан уу? Тооцоо хийх үед авсан сэргээх кодоо оруулна уу.','Broken placeholder'=>'Эвдэрсэн орлуулагч','Build'=>'Бүтээц','Built'=>'Бүтээгдсэн','Bulk actions apply only to the selected language of each selected component.'=>'Бөөнөөр хийх үйлдлүүд нь сонгосон бүрэлдэхүүн хэсэг бүрийн зөвхөн сонгосон хэлэнд хэрэгжинэ.','Bulk actions apply to every matching language of each selected component.'=>'Бөөнөөр хийх үйлдлүүд нь сонгосон бүрэлдэхүүн хэсэг бүрийн таарах бүх хэлэнд хэрэгжинэ.','Bulk download:'=>'Бөөнөөр татах:','Bulk request:'=>'Бөөнөөр хүсэх:','Bulk update:'=>'Бөөнөөр шинэчлэх:','Bundled with the plugin'=>'Плагинтай хамт ирсэн','Bundled with the theme'=>'Загвартай хамт ирсэн','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Идэвхжүүлэх дээр дарснаар та дээр жагсаасан мэдээллийг Babilim руу илгээхийг зөвшөөрч байна.','By continuing you confirm that you have the right to upload this component.'=>'Үргэлжлүүлснээр та энэ бүрэлдэхүүн хэсгийг байршуулах эрхтэй гэдгээ баталгаажуулж байна.','Cancel'=>'Цуцлах','Category'=>'Ангилал','Check again'=>'Дахин шалгах','Check again now'=>'Одоо дахин шалгах','Checkout is not available for this site right now.'=>'Одоогоор энэ сайтад тооцоо хийх боломжгүй байна.','Choose'=>'Сонгох','Choose a category…'=>'Ангилал сонгох…','Choose a language'=>'Хэл сонгох','Choose a language…'=>'Хэл сонгох…','Clear filters'=>'Шүүлтүүрийг цэвэрлэх','Close'=>'Хаах','Component'=>'Бүрэлдэхүүн хэсэг','Confirm'=>'Баталгаажуулах','Conflicting keys'=>'Зөрчилтэй түлхүүрүүд','Continue'=>'Үргэлжлүүлэх','Continue next batch (%d left)'=>'Дараагийн багцыг үргэлжлүүлэх (%d үлдсэн)','Continuing…'=>'Үргэлжилж байна…','Could not back up %s before replacing it.'=>'%s-г солихын өмнө нөөцлөж чадсангүй.','Could not create the package archive.'=>'Багцын архивыг үүсгэж чадсангүй.','Could not determine active components; the existing merged index was left unchanged.'=>'Идэвхтэй бүрэлдэхүүн хэсгүүдийг тодорхойлж чадсангүй; одоо байгаа нэгтгэсэн индексийг өөрчлөөгүй.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Суулгасан плагин/сэдвүүдийг тодорхойлж чадсангүй; цэвэрлэгээг алгассан, юу ч устгаагүй.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'WordPress.org-ийн локалуудын бүрэн жагсаалтыг үйлчилгээнээс ачаалж чадсангүй тул одоогоор өөр хэл нэмэх боломжгүй.','Could not move %s into place.'=>'%s-г байранд нь шилжүүлж чадсангүй.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\'-ийн нэгтгэсэн индексийг байрлуулж чадсангүй; өмнөх ашиглагдаж байсан индексийг (байсан бол) дутуу шинэчлэгдсэн хэвээр үлдээхийн оронд устгасан. Дараагийн удаа амжилттай дахин байгуулах хүртэл энэ локалд үндсэн домэйны нэмэлтийг ашиглахгүй.','Could not open zip: %s'=>'Zip-ийг нээж чадсангүй: %s','Could not prepare %s for rollback.'=>'%s-г буцаалтад бэлтгэж чадсангүй.','Could not read %s back after moving it into place.'=>'%s-г байрлуулсны дараа буцааж унших боломжгүй байлаа.','Could not read: %s'=>'Уншиж чадсангүй: %s','Could not restore the purchase: %s'=>'Худалдан авалтыг сэргээж чадсангүй: %s','Could not show a new restore code: %s'=>'Шинэ сэргээх код харуулж чадсангүй: %s','Could not stage %s'=>'%s-г түр байршуулж чадсангүй','Could not stage default/%s'=>'default/%s-г түр байршуулж чадсангүй','Could not start checkout: %s'=>'Тооцоо хийж эхлэж чадсангүй: %s','Could not verify entry count for %s'=>'%s-ийн бичлэгийн тоог шалгаж чадсангүй','Could not write the downloaded package to disk.'=>'Татаж авсан багцыг диск рүү бичиж чадсангүй.','Could not write the staged merged index.'=>'Бэлтгэсэн нэгтгэсэн индексийг бичиж чадсангүй.','Current translation'=>'Одоогийн орчуулга','Custom overrides'=>'Өөрийн дарж бичилтүүд','Danger zone'=>'Аюултай бүс','Default supplement entry count mismatch.'=>'Default нэмэлтийн бичлэгийн тоо таарсангүй.','Delete all Babilim data on uninstall'=>'Устгах үед Babilim-ийн бүх өгөгдлийг устгах','Disable Babilim'=>'Babilim-ийг идэвхгүй болгох','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim-ийг идэвхгүй болгох уу? Суулгасан орчуулгууд хадгалагдах боловч цаашид шалгалт, татаалт хийгдэхгүй.','Don\'t share'=>'Хуваалцахгүй','Download'=>'Татах','Downloaded and installed.'=>'Татаж аваад суулгасан.','Downloading…'=>'Татаж байна…','Downloads: %1$d/%2$d (%3$s)'=>'Татаалт: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Бүрэлдэхүүн хэсэг бүрийн локал бүрийн хуваалцсан үндсэн домэйны нэмэлтэд оруулсан хувь нэмэр.','Enable Babilim'=>'Babilim-ийг идэвхжүүлэх','Enabling…'=>'Идэвхжүүлж байна…','English (United States)'=>'Англи (Америкийн Нэгдсэн Улс)','Entries'=>'Бичлэгүүд','Entry count mismatch for %s'=>'%s-ийн бичлэгийн тоо таарсангүй','Error reports'=>'Алдааны тайлан','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Суулгасан бүх плагин/сэдэв тус бүрийн: slug, хувилбар, текст домэйн, wp.org-д бүртгэлтэй эсэх, өөрийн багтсан хэлний бүсүүд, мөн аль хэлний бүсэд Babilim-ийн орчуулгыг аль хэдийн суулгасан зэрэг.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Энэ сайтад ашиглагдаж буй бүх локал (сайтын локал, суулгасан хэлний багцууд, хэрэглэгчдийн локал болон гараар нэмсэн локалууд). Ямар ч локалд онцгой хандахгүй.','Excluded'=>'Хасагдсан','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Бусад нэр эсвэл өргөтгөлтэй файлууд, мөн uploads, cache, logs, backup, data, vendor, node_modules, languages хавтсууд, нууц файлууд, эсвэл нэр нь нийтлэг нууц мэдээллийн хэв маягтай таарах файлууд (wp-config*, .env*, *.sql, *.log, *.pem, *.key) орохгүй. Код файлууд таны хуваалцахыг хүсэхгүй байж болох текст эсвэл өгөгдөл агуулсан хэвээр байж болно; эргэлзэж байвал шалгана уу. Үйлчилгээ ирэх үед ижил төрлийн файлуудыг дахин хасдаг.','Free'=>'Үнэгүй','Free-plan slots'=>'Үнэгүй багцын слотууд','General'=>'Ерөнхий','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Хэрэв үүнийг идэвхжүүлбэл устгах үед энэ сайтын таниулбар мөн устгагдана. Дараа нь энэ сайтад холбогдсон төлбөртэй лицензийг автоматаар сэргээх боломжгүй; үүнийг буцааж авахын тулд та %s хаягаар Babilim-ийн дэмжлэгтэй холбогдох шаардлагатай болно.','Included'=>'Орсон','Included in index'=>'Индексэд орсон','Install available translations automatically'=>'Боломжтой орчуулгуудыг автоматаар суулгах','Installed'=>'Суулгасан','Installed translations are kept, but no further checks or downloads will run.'=>'Суулгасан орчуулгууд хадгалагдах боловч цаашид шалгалт, татаж авалт хийгдэхгүй.','Installed · %s'=>'Суулгасан · %s','Installed · built for %1$s, this site has %2$s'=>'Суулгасан · %1$s-д зориулан бүтээгдсэн, энэ сайт %2$s хувилбартай','Installed · built for %s'=>'Суулгасан · %s-д зориулан бүтээгдсэн','Installed · built for %s, all free-plan slots for this site are used'=>'Суулгасан · %s-д зориулан бүтээсэн, энэ сайтын үнэгүй багцын бүх слотыг ашигласан','Installed · built for %s, new version failed'=>'Суулгасан · %s-д зориулан бүтээсэн, шинэ хувилбар амжилтгүй боллоо','Installed · built for %s, new version not covered by the free service plan'=>'Суулгасан · %s-д зориулан бүтээсэн, шинэ хувилбар нь үнэгүй үйлчилгээний багцад багтаагүй','Installed · built for %s, new version scheduled'=>'Суулгасан · %s-д зориулан бүтээгдсэн, шинэ хувилбарыг товлосон','Installed · built for %s, translating the new version…'=>'Суулгасан · %s-д зориулан бүтээгдсэн, шинэ хувилбарыг орчуулж байна…','Installed · built for a different version'=>'Суулгасан · өөр хувилбарт зориулан бүтээгдсэн','Installed · built for a different version, all free-plan slots for this site are used'=>'Суулгасан · өөр хувилбарт зориулан бүтээсэн, энэ сайтын үнэгүй багцын бүх слотыг ашигласан','Installed · built for a different version, new version failed'=>'Суулгасан · өөр хувилбарт зориулан бүтээсэн, шинэ хувилбар амжилтгүй боллоо','Installed · built for a different version, new version not covered by the free service plan'=>'Суулгасан · өөр хувилбарт зориулан бүтээсэн, шинэ хувилбар нь үнэгүй үйлчилгээний багцад багтаагүй','Installed · built for a different version, new version scheduled'=>'Суулгасан · өөр хувилбарт зориулан бүтээгдсэн, шинэ хувилбарыг товлосон','Installed · built for a different version, translating the new version…'=>'Суулгасан · өөр хувилбарт зориулан бүтээгдсэн, шинэ хувилбарыг орчуулж байна…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Үүнийг үйлчилгээний хостинг үзүүлэгч хадгалж, орчуулга гаргахын тулд хиймэл оюун ухааны загварууд боловсруулна.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Бүгдийг устгах эсвэл энэ залгаасыг устгахад миний өөрийн орчуулгын дарж бичилтүүдийг хадгалах.','Language'=>'Хэл','Language:'=>'Хэл:','Languages'=>'Хэлүүд','Languages found on this site: %s.'=>'Энэ сайтаас олдсон хэлүүд: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'%1$s-ийн сүүлийн цэвэрлэгээ: %2$d шинээр тэмдэглэсэн, %3$d файл устгасан, %4$d бүртгэл арилгасан.','Maintenance'=>'Засвар үйлчилгээ','Maintenance status is not available right now.'=>'Засвар үйлчилгээний төлөвийг одоогоор харах боломжгүй байна.','Manifest unavailable: %s'=>'Манифест боломжгүй: %s','Negation reversed'=>'Үгүйсгэл урвуугаараа болсон','No'=>'Үгүй','No build is available to download for this locale.'=>'Энэ локалд татаж авах боломжтой build байхгүй байна.','No cleanup has run yet.'=>'Цэвэрлэгээ хараахан хийгдээгүй байна.','No components match these filters. %s'=>'Эдгээр шүүлтүүрт тохирох бүрэлдэхүүн хэсэг алга. %s','No components synced yet.'=>'Бүрэлдэхүүн хэсэг хараахан синхрончлогдоогүй байна.','No installed translation matches.'=>'Тохирох суулгасан орчуулга олдсонгүй.','No language is managed yet.'=>'Одоогоор удирдаж буй хэл алга.','No pending challenge for this nonce.'=>'Энэ nonce-д хүлээгдэж буй challenge алга.','No pending challenge to verify.'=>'Баталгаажуулах хүлээгдэж буй сорилт алга.','No plugins or themes found.'=>'Плагин эсвэл сэдэв олдсонгүй.','No previous build to roll back to.'=>'Буцаах өмнөх build алга.','No record for %s'=>'%s-д зориулсан бүртгэл олдсонгүй','No site id is on file to rotate a token for.'=>'Токен шинэчлэх сайтын ID бүртгэлд алга.','No — component inactive'=>'Үгүй — бүрэлдэхүүн хэсэг идэвхгүй','No — component removed'=>'Үгүй — бүрэлдэхүүн хэсэг устгагдсан','No — installed version differs from the active one'=>'Үгүй — суулгасан хувилбар идэвхтэй хувилбараас өөр байна','Not a valid server_build_id: %s'=>'Хүчинтэй server_build_id биш: %s','Not covered by the free service plan'=>'Үнэгүй үйлчилгээний багцад багтаагүй','Not installed'=>'Суулгаагүй','Not registered yet'=>'Хараахан бүртгэгдээгүй','Not supported'=>'Дэмжигдээгүй','Not verified'=>'Баталгаажаагүй','Note (optional)'=>'Тайлбар (заавал биш)','Nothing to choose.'=>'Сонгох зүйл алга.','Nothing to confirm.'=>'Баталгаажуулах зүйл алга.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Анхдагчаар унтраалттай: залгаасыг устгахад энэ сайтын таниулбар хадгалагдах тул дахин суулгахад ашиглах боломжтой.','One or more served files no longer match the manifest.'=>'Нэг буюу хэд хэдэн үйлчилсэн файл манифесттэй таарахаа больсон.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Энэ сайтад зориулсан нэг удаагийн худалдан авалт: %1$s %2$s. Ирээдүйн бүх орчуулгын шинэчлэлтийг агуулна. Төлбөрийг Paddle шинэ табд боловсруулна.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Үүнийг зөвхөн сүлжээний администратор хийж чадна, учир нь энэ нь энэ сүлжээний бүх сайтад хуваалцдаг орчуулгын файлуудыг өөрчилдөг.','Only plugins and themes can be packaged.'=>'Зөвхөн залгаас болон загваруудыг багцалж болно.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'WordPress.org дээр байхгүй плагин эсвэл сэдвийн файлуудыг байршуулахыг та баталгаажуулсан тохиолдолд л: бүх .php болон .js файл, бүх block.json файл, мөн тухайн бүрэлдэхүүн хэсгийн үндсэн хавтас дахь readme.txt, readme.md, style.css, theme.json файлуудыг нууц мэдээлэл агуулдаг файлуудын түгээмэл хэв маягтай таарах файлуудыг хассаны дараа zip хэлбэрээр байршуулна.','Open Babilim settings'=>'Babilim-ийн тохиргоог нээх','Original language'=>'Эх хэл','Original string'=>'Жинхэнэ мөр','Paid'=>'Төлбөртэй','Partner'=>'Түнш','Please check that your site can be reached from the internet, then try again.'=>'Таны сайтад интернетээс хандах боломжтой эсэхийг шалгаад дахин оролдоно уу.','Please choose a category for this report.'=>'Энэ тайланд зориулж ангилал сонгоно уу.','Plugin'=>'Плагин','Plugin · %s'=>'Плагин · %s','Plugins'=>'Плагинууд','Preview'=>'Урьдчилан харах','Purchase restored. This site is now licensed.'=>'Худалдан авалт сэргэлээ. Энэ сайт одоо лицензтэй боллоо.','Re-parsed entry count did not match the built index.'=>'Дахин задлан шинжилсэн оруулгын тоо байгуулсан индекстэй таарсангүй.','Re-verify'=>'Дахин баталгаажуулах','Rebuild index now'=>'Индексийг одоо дахин үүсгэх','Refusing to write outside the Babilim language-file directory.'=>'Babilim-ийн хэлний файлын хавтаснаас гадна бичихээс татгалзаж байна.','Registration response was missing required fields.'=>'Бүртгэлийн хариунд шаардлагатай талбарууд дутуу байна.','Registration restarted.'=>'Бүртгэл дахин эхэллээ.','Remove'=>'Устгах','Remove everything Babilim installed'=>'Babilim-ийн суулгасан бүгдийг устгах','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim-ийн суулгасан бүхнийг устгах уу? Энэ нь Babilim-ийн энэ сайтын бүх плагин болон загварт суулгасан бүх хэлний файлыг устгана.','Remove the %2$s translation of %1$s from this site?'=>'%1$s-ийн %2$s хэл дээрх орчуулгыг энэ сайтаас устгах уу?','Removed %d installed component.'=>'Суулгасан %d бүрэлдэхүүн хэсгийг хаслаа.' . "\0" . 'Суулгасан %d бүрэлдэхүүн хэсгийг хаслаа.','Removed after a failed integrity check'=>'Бүрэн бүтэн байдлын шалгалтад бүтэлгүйтсний дараа устгасан','Removed.'=>'Устгасан.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Babilim-ийн энэ сайтын бүх плагин болон загварт суулгасан бүх хэлний файлыг устгана.','Report a problem'=>'Асуудлыг мэдэгдэх','Report translation'=>'Орчуулгын талаар мэдээлэх','Request newer translation'=>'Шинэ орчуулга хүсэх','Request translation'=>'Орчуулга хүсэх','Requestable'=>'Хүсэх боломжтой','Requesting…'=>'Хүсэж байна…','Restart registration'=>'Бүртгэлийг дахин эхлүүлэх','Restore code'=>'Сэргээх код','Restore purchase'=>'Худалдан авалтыг сэргээх','Retry request'=>'Хүсэлтийг дахин илгээх','Roll back'=>'Буцаах','Roll back and report'=>'Буцаагаад мэдэгдэх','Roll back and send report'=>'Буцаагаад тайлан илгээх','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s-ийн %2$s орчуулгыг өмнөх бүтээлт рүү буцаах уу?','Rolled back and reported.'=>'Буцаагаад мэдэгдлээ.','Rolled back to the previous build.'=>'Өмнөх хувилбар руу буцаалаа.','Rolled back, but the report could not be sent: %s'=>'Буцаасан боловч тайланг илгээж чадсангүй: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Буцаах нь \'%1$s\' (%2$s) файлыг дарж бичих болно. Энэ файл одоо өөр суулгасан бүрэлдэхүүн хэсэгт (%3$s) үйлчилж байна. Юу ч өөрчлөгдөөгүй.','Rotate-token response was missing site_token.'=>'Токен шинэчлэх хариуд site_token алга байна.','Save changes'=>'Өөрчлөлтийг хадгалах','Scheduled, waiting to be processed'=>'Товлосон, боловсруулахыг хүлээж байна','Search'=>'Хайх','Search components'=>'Бүрэлдэхүүн хэсгүүдийг хайх','Search the installed translations'=>'Суулгасан орчуулгуудаас хайх','Select all'=>'Бүгдийг сонгох','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Цөөн бүрэлдэхүүн хэсэг сонгоно уу: нэг удаад дээд тал нь %1$d үйлдэл хийнэ (та %2$d сонгосон байна).','Send report'=>'Тайлан илгээх','Service plan'=>'Үйлчилгээний багц','Settings'=>'Тохиргоо','Share error reports'=>'Алдааны тайлан хуваалцах','Share this report'=>'Энэ тайланг хуваалцах','Show a new restore code'=>'Шинэ сэргээх код харуулах','Show the "Report translation" entry in the admin toolbar'=>'Админы хэрэгслийн самбарт "Орчуулгын талаар мэдээлэх" оруулгыг харуулах','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Энэ бүрэлдэхүүн хэсгийн зарим текстийг зохиогч нь кодод шууд бичсэн тул хэлний багцаар орчуулах боломжгүй.','Status'=>'Төлөв','Status unknown'=>'Төлөв тодорхойгүй','String context'=>'Стрингийн контекст','Suggested translation'=>'Санал болгосон орчуулга','Supplementary translation index'=>'Нэмэлт орчуулгын индекс','Supplementary translation index rebuilt.'=>'Нэмэлт орчуулгын индекс дахин бүтээгдлээ.','Supplementary translation maintenance'=>'Нэмэлт орчуулгын засвар үйлчилгээ','Supplementary translations'=>'Нэмэлт орчуулгууд','Sweep aborted without orphaning anything: %s.'=>'Цэвэрлэгээг юуг ч өнчрүүлэлгүйгээр зогсоосон: %s.','Sweep complete: %d file deleted.'=>'Цэвэрлэгээ дууслаа: %d файл устгагдлаа.' . "\0" . 'Цэвэрлэгээ дууслаа: %d файл устгагдлаа.','Sweep now'=>'Одоо цэвэрлэх','Sync complete.'=>'Синк дууслаа.','Thank you. Your report was sent.'=>'Баярлалаа. Таны тайланг илгээлээ.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Энэ бүрэлдэхүүн хэсэг уг сайтад суулгаагүй тул түүнд орчуулга хүсэх боломжгүй.','That does not look like a restore code.'=>'Энэ нь сэргээх код шиг харагдахгүй байна.','That is not a valid WordPress locale code. Nothing was saved.'=>'Энэ нь хүчинтэй WordPress локалын код биш байна. Юу ч хадгалагдаагүй.','That is not a valid build identifier.'=>'Энэ нь хүчинтэй бүтээлтийн танигч биш.','The change could not be recorded in the translation index; please try again.'=>'Өөрчлөлтийг орчуулгын индекст бүртгэж чадсангүй. Дахин оролдоно уу.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Цэвэрлэгээ хийгдсэн боловч зарим өөрчлөлтийг орчуулгын индексэд бүртгэж чадсангүй; дараагийн цэвэрлэгээ дахин оролдоно.','The component has no files that can be uploaded.'=>'Энэ бүрэлдэхүүн хэсэгт байршуулах боломжтой файл алга.','The component is not inside the plugins or themes directory.'=>'Бүрэлдэхүүн хэсэг нь залгаас эсвэл загваруудын хавтас дотор байхгүй байна.','The component\'s main file was not found.'=>'Бүрэлдэхүүн хэсгийн үндсэн файл олдсонгүй.','The download response was missing a usable location.'=>'Татаж авах хариунд ашиглах боломжтой байршил алга байна.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Энэ оруулга нь Babilim-ийн энэ сайтад суулгасан орчуулгуудаас хайж, аль нэгийн талаар мэдээлэх самбарыг нээнэ.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" талбар хэт урт байна: %2$d тэмдэгттэй бөгөөд дээд хязгаар нь %3$d. Юу ч илгээгээгүй; богиносгоод дахин оролдоно уу.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Өгөгдсөн \'%1$s\' домэйн нь багцын манифестийн \'%2$s\' slug-тай ч, \'%3$s\' text_domain-тай ч таарахгүй байна.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\'-ийн нэгтгэсэн индексийг дахин байгуулсан боловч орчуулгын индекс үүнийг бүртгэж чадсангүй; дараагийн дахин байгуулалт дахин оролдоно.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Эх текст болон түүнээс гарсан орчуулгуудыг ижил хувилбарыг суулгасан бусад сайтуудад өгөх болно.','The package declares no main translation file.'=>'Багц үндсэн орчуулгын файлыг зарлаагүй байна.','The package has no %s for its own text domain.'=>'Багц нь өөрийн текст домэйнд зориулсан %s файлгүй байна.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Багцын манифестийн \'%1$s\' төрөл хүсэсэн \'%2$s\' төрөлтэй таарахгүй байна.','The package produced no servable main translation file.'=>'Багцаас үйлчлэх боломжтой үндсэн орчуулгын файл гарсангүй.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Багцын текст домэйн \'%1$s\' нь энэ сайтын бүрэлдэхүүн хэсгийн хуулбарын (\'%2$s\') текст домэйнтэй таарахгүй тул суулгаагүй.','The packaged component could not be read.'=>'Багцалсан бүрэлдэхүүн хэсгийг уншиж чадсангүй.','The registration challenge is not in the expected form.'=>'Бүртгэлийн сорилт хүлээгдэж буй хэлбэртэй биш байна.','The report could not be sent.'=>'Тайланг илгээж чадсангүй.','The search could not be completed.'=>'Хайлтыг дуусгаж чадсангүй.','The service asked this site to wait before syncing again.'=>'Үйлчилгээ энэ сайтыг дахин синк хийхээс өмнө хүлээхийг хүссэн.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Үйлчилгээ таны сайтад хүрч чадсангүй. Галт хана, аюулгүй байдлын плагин эсвэл хостын дүрэм хүсэлтийг блоклож байж магадгүй; /wp-json/babilim/v1/challenge руу хандах хүсэлтийг зөвшөөрнө үү.','The service\'s upload offer was incomplete.'=>'Үйлчилгээний байршуулах санал бүрэн бус байлаа.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'\'%1$s\' текст домэйн (%2$s) өөр суулгасан бүрэлдэхүүн хэсэгт (%3$s) аль хэдийн үйлчилж байна. Юу ч суулгаагүй.','The upload is kept until you ask Babilim to delete it.'=>'Та Babilim-ээс устгахыг хүсэх хүртэл байршуулсан өгөгдөл хадгалагдана.','Theme'=>'Загвар','Theme · %s'=>'Сэдэв · %s','Themes'=>'Сэдвүүд','There is no upload in progress.'=>'Явагдаж буй байршуулалт алга.','There is no upload waiting for confirmation.'=>'Баталгаажуулалт хүлээж буй байршуулалт алга.','These are the languages this site uses. You can change them in %s.'=>'Эдгээр нь энэ сайтын ашигладаг хэлүүд юм. Та тэдгээрийг %s хэсгээс өөрчлөх боломжтой.','These fields will be sent:'=>'Дараах талбаруудыг илгээнэ:','This build is not one this site currently knows about for this component/locale.'=>'Энэ build нь энэ сайтад тухайн бүрэлдэхүүн хэсэг/локалын хувьд одоогоор мэдэгдэж буй build биш байна.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Энэ бүрэлдэхүүн хэсэг хувилбарын дугаараа зарлаагүй тул түүнд орчуулга хүсэх боломжгүй.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Энэ бүрэлдэхүүн хэсэг үйлчилгээний хүлээн авах хэмжээнээс том тул байршуулах боломжгүй.','This component was already uploaded. Babilim is checking it now.'=>'Энэ бүрэлдэхүүн хэсгийг аль хэдийн байршуулсан. Babilim одоо шалгаж байна.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Энэ бүрэлдэхүүн хэсгийн хувилбарын дугаар %d тэмдэгтээс урт бөгөөд Babilim үүнийг боловсруулж чадахгүй тул орчуулга хүсэх боломжгүй.','This issues a new restore code and the previous one stops working. Continue?'=>'Энэ нь шинэ сэргээх код олгох бөгөөд өмнөх код ажиллахаа болино. Үргэлжлүүлэх үү?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Энэ сүлжээнд сайт хэт олон тул тус бүрийг нь шалгах боломжгүй бөгөөд зарим нь плагиныг устгах үед Babilim-ийн таниулбараа устгахаар тохируулагдсан байж магадгүй. Ийм сайтад холбогдсон төлбөртэй лицензийг автоматаар сэргээх боломжгүй болно; та %s хаягаар Babilim-ийн дэмжлэгтэй холбогдох шаардлагатай. Таниулбаруудыг хадгалахын тулд Цуцлах дээр дарж, сайт тус бүрийн Babilim-ийн тохиргоонд "Устгах үед Babilim-ийн бүх өгөгдлийг устгах" сонголтыг болиулаад, дахин идэвхгүй болгоно уу. Ямар ч тохиолдолд идэвхгүй болгох уу?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Энэ плагины өөрийн хувилбар. Хэт хуучирсан тул үйлчилгээтэй холбогдох боломжгүй бол үйлчилгээ танд шинэчлэхийг хэлж чадна.','This report does not name a valid plugin or theme and locale.'=>'Энэ тайланд хүчинтэй плагин эсвэл сэдэв болон локалын нэр заагдаагүй байна.','This report does not name an installed string.'=>'Энэ тайлан Суулгасан мөрийг заагаагүй байна.','This report is missing a valid build to report against.'=>'Энэ тайланд холбогдох хүчинтэй хувилбар алга байна.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Энэ тайланг GitHub дээр олон нийтэд нийтлэх бөгөөд гуравдагч этгээдүүд хадгалж магадгүй.','This restore code was not recognised for this site.'=>'Энэ сэргээх кодыг энэ сайтад танихгүй байна.','This site already has an active registration that can no longer be recovered automatically.'=>'Энэ сайт идэвхтэй бүртгэлтэй боловч түүнийг автоматаар сэргээх боломжгүй болсон.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Энэ сайт %2$d хэлний %1$d бүрэлдэхүүн хэсэгтэй бөгөөд %3$d шалгалтын багц шаардлагатай; Babilim нэг ажиллалтад дээд тал нь %4$d боловсруулна. Тохиргооноос удирдах хэлний тоог бууруулах эсвэл ашиглаагүй плагин, сэдвүүдийг идэвхгүй болгоод одоо Дахин шалгах дарна уу.','This site has no purchase to show a code for.'=>'Энэ сайтад код харуулах худалдан авалт алга.','This site is already licensed. Reload the page.'=>'Энэ сайт аль хэдийн лицензтэй байна. Хуудсыг дахин ачаална уу.','This site is not registered with Babilim yet.'=>'Энэ сайт Babilim-д хараахан бүртгэгдээгүй байна.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Энэ сайт нэг удаагийн синхрончлолд үйлчилгээний хүлээн авах хэмжээнээс хэтэрсэн тул зарим зүйл орхигдсон: %1$d бүрэлдэхүүн хэсэг ба %2$d хэл.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Энэ сайт олон сайтын сүлжээний нэг хэсэг бөгөөд шинэ орчуулгыг автоматаар суулгадаггүй. Аль хэдийн суулгасан орчуулгууд хэвээр шинэчлэгдэнэ.','This site is verified.'=>'Энэ сайт баталгаажсан.','This site must be verified first.'=>'Энэ сайтыг эхлээд баталгаажуулах шаардлагатай.','This site\'s URL, so the service can verify you own it.'=>'Энэ сайтын URL. Үүгээр үйлчилгээ таныг сайтын эзэмшигч гэдгийг баталгаажуулна.','This site\'s address is too long for Babilim to register.'=>'Энэ сайтын хаяг Babilim-д бүртгэхэд хэт урт байна.','This site\'s configured locale.'=>'Энэ сайтад тохируулсан локал.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Энэ сайтын суулгалтын нийтийн түлхүүр. Хүсэлтүүд үнэхээр энэ сайтаас ирж буйг батлахад ашиглана. Зөвхөн нийтийн хэсгийг нь илгээнэ.','This site\'s locale code is not one Babilim can register.'=>'Энэ сайтын локал код нь Babilim бүртгэж чадахгүй код байна.','This string can\'t be reported from this site.'=>'Энэ мөрийг энэ сайтаас мэдээлэх боломжгүй.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Энэ мөр нь энэ сайт дээр суулгасан орчуулгуудад байхгүй байна. Дахин хайж, жагсаалтаас сонгоно уу.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Таныг хайснаас хойш энэ орчуулга шинэчлэгдсэн. Дахин хайж, шинэ жагсаалтаас мөрийг сонгоно уу.','To translate this component, Babilim needs its source.'=>'Энэ бүрэлдэхүүн хэсгийг орчуулахын тулд Babilim-д түүний эх код хэрэгтэй.','Too many attempts. Try again tomorrow.'=>'Хэт олон оролдлого хийлээ. Маргааш дахин оролдоно уу.','Too many reports today. Try again tomorrow.'=>'Өнөөдөр хэт олон тайлан илгээсэн байна. Маргааш дахин оролдоно уу.','Too many requests.'=>'Хэт олон хүсэлт илгээлээ.','Toolbar'=>'Хэрэгслийн самбар','Translating…'=>'Орчуулж байна…','Translation does not load'=>'Орчуулга ачаалагдахгүй байна','Translation failed'=>'Орчуулга амжилтгүй боллоо','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Таны %s дотор байрлуулсан орчуулгын файлууд Babilim-ийнхээс үргэлж давуу эрхтэй. Та үүнийг сонгохоо болихгүй л бол тэдгээр хадгалагдана.','Translation requested.'=>'Орчуулга хүссэн.','Translations'=>'Орчуулгууд','Type'=>'Төрөл','Type at least 2 characters to search.'=>'Хайхын тулд дор хаяж 2 тэмдэгт оруулна уу.','Unexpected HTTP %d response.'=>'Хүлээгдээгүй HTTP %d хариу ирлээ.','Uninstall'=>'Устгах','Unknown kind: %s'=>'Үл мэдэгдэх kind: %s','Unsafe domain: %s'=>'Аюултай домэйн: %s','Unsafe locale: %s'=>'Аюултай локал: %s','Unsafe slug: %s'=>'Аюултай slug: %s','Unsafe text_domain: %s'=>'Аюултай text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Хүлээгдэж буй 20 хүртэлх оношилгооны үйл явдал (жишээ нь бүрэн бүтэн байдлын шалгалтад унасан файл), тус бүр нь зөвхөн код, бүрэлдэхүүн хэсэг, локал бөгөөд ямар ч мөрийн агуулга эсвэл орчуулсан текст огт байхгүй.','Update'=>'Шинэчлэх','Update available'=>'Шинэчлэл бэлэн','Updates'=>'Шинэчлэлтүүд','Updating…'=>'Шинэчилж байна…','Upgrade this site'=>'Энэ сайтыг сайжруулах','Upload and request'=>'Байршуулж, хүсэлт илгээх','Upload cancelled.'=>'Байршуулалтыг цуцалсан.','Upload complete — translation requested.'=>'Байршуулалт дууслаа — орчуулга хүссэн.','Upload expired before it finished'=>'Байршуулалт дуусахаас өмнө хугацаа дууссан','Upload in progress — continue or cancel'=>'Байршуулалт явагдаж байна — үргэлжлүүлэх эсвэл цуцлах','Upload this component?'=>'Энэ бүрэлдэхүүн хэсгийг байршуулах уу?','Upload was not accepted'=>'Байршуулалтыг хүлээн аваагүй','Uploading'=>'Байршуулж байна','Uploading part %1$d of %2$d…'=>'%2$d-аас %1$d-р хэсгийг байршуулж байна…','Uploading…'=>'Байршуулж байна…','Verified'=>'Баталгаажсан','Verify response was missing site_token.'=>'Баталгаажуулалтын хариуд site_token алга байна.','Version %s'=>'Хувилбар %s','What is sent when Babilim checks this site'=>'Babilim энэ сайтыг шалгахад юу илгээгддэг вэ','What is sent when you enable Babilim'=>'Babilim-ийг идэвхжүүлэх үед юу илгээгдэх вэ','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Babilim дотор ямар нэг зүйл амжилтгүй болоход алдааны тайланг Babilim үйлчилгээнд илгээж, GitHub дээр нийтэд нээлттэй асуудлын бүртгэл (issue) болгон нийтлүүлнэ. Тайланг энэ сайтаас илгээх бөгөөд Babilim үйлчилгээнд илгээдэг бусад бүх хүсэлттэй ижил баталгаажуулалт ашиглана. Үйлчилгээ зөвхөн алдааны код болон хувилбаруудыг GitHub дээр нийтэд нээлттэй асуудлын бүртгэл болгон нийтэлнэ; уг бүртгэлд сайтын хаяг, агуулга болон файлын зам орохгүй. Анхдагчаар унтраалттай.','Where you saw this (optional)'=>'Үүнийг хаанаас харсан бэ (заавал биш)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Үүнийг асаасан үед үйлчилгээний таны удирддаг хэлнүүдэд боломжтой гэж жагсаасан орчуулгуудыг өдөрт хоёр удаагийн синк үеэр суулгана.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Энэ контекстэд буруу','Wrong meaning'=>'Буруу утга','Wrong plural form'=>'Буруу олон тооны хэлбэр','Wrong term'=>'Буруу нэр томьёо','Yes'=>'Тийм','You are not allowed to do this.'=>'Танд энэ үйлдлийг хийх эрх байхгүй.','Your PHP version, for compatibility.'=>'Таны PHP-ийн хувилбар. Нийцтэй байдлыг шалгахад ашиглана.','Your WordPress version, to serve compatible translation files.'=>'Таны WordPress-ийн хувилбар. Нийцтэй орчуулгын файл өгөхөд ашиглана.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Таны шинэ сэргээх код: %s. Аюулгүй газар хадгална уу — өмнөх код ажиллахаа больсон.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Таны тайланг AI загварууд автоматаар боловсруулах бөгөөд бусад сайтад энэ орчуулгыг сайжруулж магадгүй.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Таны сайт хариулсан боловч хүлээгдсэн хариу биш байна. REST API-г өөр плагин өөрчилж байж магадгүй эсвэл тэр endpoint кэшлэгдсэн байж болзошгүй; /wp-json/babilim/v1/challenge-ийг кэшлэх болон дахин бичихээс чөлөөлнө үү.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Таны сайт хэт удаан хариу өглөө. Дараа дахин оролдож, хост тань хэт удаан эсвэл ачаалал ихтэй биш эсэхийг шалгана уу.','Zip has no manifest.json.'=>'Zip-д manifest.json байхгүй байна.','Zip is missing expected default file: %s'=>'Zip-д шаардлагатай default файл байхгүй байна: %s','Zip is missing expected file: %s'=>'Zip-д шаардлагатай файл байхгүй байна: %s','_manifest.json has an unexpected structure'=>'_manifest.json-ийн бүтэц хүлээгдэж байснаас өөр байна','could not read _manifest.json: %s'=>'_manifest.json-г уншиж чадсангүй: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest байхгүй эсвэл хүчингүй \'%s\' агуулсан байна.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest-ийн \'server_build_id\' нь хүчинтэй build id биш байна.','failed to parse _manifest.json: %s'=>'_manifest.json-г задлан шинжилж чадсангүй: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'энэ нь удирдагдаж буй нийт %2$d бүрэлдэхүүн хэсгийн %1$d-г өнчрүүлнэ (талаас илүү)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'энэ нь удирдагдаж буй бүх %1$s бүрэлдэхүүн хэсгийг (%2$d-ийн %2$d) өнчрүүлнэ','l10n.php entry count mismatch for %s'=>'%s-ийн l10n.php оруулгын тоо таарахгүй байна','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json-д хүчингүй \'default_domain_entries\' байна.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json-д хүчингүй \'default_domain_files\' байна.','manifest.json in the zip is not valid JSON.'=>'Zip доторх manifest.json нь хүчинтэй JSON биш байна.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json-д \'%s\' байхгүй эсвэл хүчингүй байна.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json-д \'build_no\' байхгүй эсвэл хүчингүй байна.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json-д \'entries\' байхгүй эсвэл хүчингүй байна.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json-д \'extra_domains\' байхгүй эсвэл хүчингүй байна.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json-д \'files\' байхгүй эсвэл хүчингүй байна.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json-ийн \'%s\' хүлээгдэж буй утгатай таарахгүй байна.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json-ийн \'contract\' нь хүчинтэй хувилбарын тэмдэгт мөр биш байна.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json-ийн \'kind\' нь \'plugin\' эсвэл \'theme\' байх ёстой.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json-ийн \'server_build_id\' нь хүчинтэй build id биш байна.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json-ийн \'status\' нь \'published\' байх ёстой.','nonce must be a hexadecimal string.'=>'nonce нь арван зургаатын тэмдэгт мөр байх ёстой.','per day'=>'өдөрт','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s-ийн sha256 таарахгүй байна','sha256 mismatch for default/%s'=>'default/%s-ийн sha256 таарахгүй байна','component kind in the sweep brake messageplugin'=>'плагин','component kind in the sweep brake messagetheme'=>'сэдэв','problem report categoryOther'=>'Бусад','translation statusAvailable'=>'Боломжтой','translation statusInstalled'=>'Суулгасан']];